import {mapGetters} from 'vuex'
import {hiddenAdd, hiddenUpdate} from "@/api/safeDanger/hiddenCategory"
// import {getHiddenPCDict} from "@/utils/hiddenDict";

export default {
  name: "ComputerRoomHiddenDetail",
  computed: {
    ...mapGetters([
      'nickName',
      'companyId',
      'companyCode',
    ]),
  },
  props: {
    category: {
      type: String,
      default: null
    },
    roomId: {
      default: false
    },
    type: {
      type: Boolean,
      default: false
    },
    info: {
      type: Object,
      default: {}
    }
  },
  data() {
    return {
      // 表单参数
      form: {
        categoryId: undefined,
        type: undefined,
        content: undefined,
      },
      // options: getHiddenPCDict,
      options: [],
      //校验
      rules: {
        type: [{required: true, message: '分类标准不能为空', trigger: 'change'}],
        content: [{required: true, message: '隐患内容不能为空', trigger: 'blur'}],
      },
    }
  },
  created() {
    this.initData()
    this.showInfo();
  },
  mounted() {

  },
  methods: {
    initData() {
      this.form.categoryId = this.roomId;
    },
    showInfo() {
      // this.resetForm("form");
      if (this.type == 'edit') {
        this.form = JSON.parse(JSON.stringify(this.info));
      }
    },
    /** 提交按钮 */
    submitForm() {
      this.$refs["form"].validate(valid => {
        if (valid) {
          if (this.type == 'add') {
            hiddenAdd(this.form).then(response => {
              if (response.code === 200) {
                this.msgSuccess("新增成功");
                this.$emit('closeRoom')
              } else {
                this.msgError(response.msg);
              }
            });
          } else if (this.type == 'edit') {
            hiddenUpdate(this.form).then(response => {
              if (response.code === 200) {
                this.msgSuccess("修改成功");
                this.$emit('closeRoom')
              } else {
                this.msgError(response.msg);
              }
            });
          } 
          // else if (this.type == 'delete') {}
        }
      });
    },
  }
}
